 void clear(){id=UUID.randomUUID().toString();audio=null;for(EditText e:new EditText[]{ins,nome,etnia,povo,territorio,obs,notas[0],notas[1],notas[2]})e.setText("");ausente.setChecked(false);inicio="";fim="";ciencia.setChecked(false);status.setText("Aguardando");}
 void start(boolean test){if(rec!=null)return;if(!test&&(val(ins).isEmpty()||val(nome).isEmpty()||!ciencia.isChecked())){msg("Informe inscrição, nome e ciência.");return;}if(!test&&audio!=null){msg("Já existe áudio nesta ficha.");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},1);msg("Autorize e tente novamente.");return;}try{File f=new File(dir,id+(test?"-teste":"")+".m4a");rec=new MediaRecorder();rec.setAudioSource(MediaRecorder.AudioSource.MIC);rec.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);rec.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);rec.setOutputFile(f.getPath());rec.prepare();rec.start();paused=false;audio=f;if(!test)inicio=stamp();msg("Gravando");if(test)new Handler().postDelayed(()->{stop();play();audio=null;f.delete();},5000);}catch(Exception e){release();msg("Falha: "+e.getMessage());}}
 void toggle(){if(rec==null)return;try{if(paused)rec.resume();else rec.pause();paused=!paused;msg(paused?"Pausado":"Gravando");}catch(Exception e){msg("Falha ao pausar");}} void release(){if(rec!=null){rec.release();rec=null;}} void stop(){if(rec==null)return;try{rec.stop();fim=stamp();msg("Gravação encerrada. Confira o áudio.");}catch(Exception e){audio=null;msg("Falha na gravação");}finally{release();}} void play(){if(audio==null||rec!=null)return;try{if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(audio.getPath());player.prepare();player.start();}catch(Exception e){msg("Falha na reprodução");}}
 void save(){try{JSONObject j=snapshot(true);pdf(j,false);if(!ausente.isChecked())pdf(j,true);try(FileOutputStream o=new FileOutputStream(new File(dir,id+".json"))){o.write(j.toString(2).getBytes("UTF-8"));}msg("Avaliação salva. Nota: "+j.optString("total"));}catch(Exception e){msg("Não salvo: "+e.getMessage());}} JSONObject snapshot(boolean requireAudio)throws Exception{if(rec!=null)throw new Exception("Encerre a gravação");if(val(ins).isEmpty()||val(nome).isEmpty())throw new Exception("Informe inscrição e nome");if(requireAudio&&!ausente.isChecked()&&(audio==null||!audio.exists()||audio.length()==0))throw new Exception("Gravação necessária");JSONObject j=new JSONObject();j.put("inscricao",val(ins));j.put("nome",val(nome));if(val(banca).isEmpty()||val(banca2).isEmpty()||val(banca).equalsIgnoreCase(val(banca2)))throw new Exception("Informe dois avaliadores distintos");j.put("etnia",val(etnia));j.put("povo",val(povo));j.put("territorio",val(territorio));j.put("banca",val(banca));j.put("banca2",val(banca2));j.put("local",val(local));j.put("presenca",ausente.isChecked()?"Ausente":"Presente");j.put("inicio",inicio);j.put("fim",fim);j.put("ciencia",ciencia.isChecked());j.put("observacoes",val(obs));j.put("audio",audio==null?"":audio.getName());double total=0;JSONArray a=new JSONArray();if(!ausente.isChecked())for(int k=0;k<3;k++){double n=Double.parseDouble(val(notas[k]).replace(',','.'));if(!Double.isFinite(n)||n<0||n>max[k])throw new Exception("Nota inválida");a.put(n);total+=n;}j.put("notas",a);j.put("total",ausente.isChecked()?JSONObject.NULL:total);j.put("data",stamp());return j;}

 String read(File f)throws Exception{try(InputStream i=new FileInputStream(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){copy(i,o);return o.toString("UTF-8");}} void list(){if(rec!=null)return;File[] fs=dir.listFiles((d,n)->n.endsWith(".json"));if(fs==null)return;ArrayList<String> labels=new ArrayList<>();ArrayList<File> files=new ArrayList<>();for(File f:fs)try{JSONObject j=new JSONObject(read(f));labels.add(j.getString("inscricao")+" — "+j.getString("nome"));files.add(f);}catch(Exception e){}new AlertDialog.Builder(this).setTitle("Entrevistas salvas").setItems(labels.toArray(new String[0]),(a,k)->{try{File f=files.get(k);JSONObject j=new JSONObject(read(f));clear();id=f.getName().replace(".json","");ins.setText(j.getString("inscricao"));nome.setText(j.getString("nome"));etnia.setText(j.optString("etnia"));povo.setText(j.optString("povo"));territorio.setText(j.optString("territorio"));banca.setText(j.optString("banca"));banca2.setText(j.optString("banca2"));local.setText(j.optString("local"));ausente.setChecked("Ausente".equals(j.optString("presenca")));inicio=j.optString("inicio");fim=j.optString("fim");obs.setText(j.optString("observacoes"));ciencia.setChecked(j.optBoolean("ciencia"));for(int x=0;x<j.getJSONArray("notas").length()&&x<3;x++)notas[x].setText(j.getJSONArray("notas").getString(x));audio=j.optString("audio").isEmpty()?null:new File(dir,j.getString("audio"));msg("Registro aberto");}catch(Exception e){msg("Falha ao abrir");}}).show();}
 void copy(InputStream i,OutputStream o)throws IOException{byte[] b=new byte[65536];int n;while((n=i.read(b))!=-1)o.write(b,0,n);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;try{if(r==5){if(pendingPdf==null)throw new IOException("Documento indisponível");try(InputStream i=new FileInputStream(pendingPdf);OutputStream o=getContentResolver().openOutputStream(d.getData())){copy(i,o);}pendingPdf=null;msg("PDF exportado");}if(r==2){if(audio!=null){msg("Já existe áudio");return;}String type=getContentResolver().getType(d.getData());String ext=type!=null&&type.contains("mpeg")?".mp3":type!=null&&type.contains("wav")?".wav":type!=null&&type.contains("ogg")?".ogg":type!=null&&type.contains("webm")?".webm":".m4a";File f=new File(dir,id+ext);try(InputStream i=getContentResolver().openInputStream(d.getData());OutputStream o=new FileOutputStream(f)){copy(i,o);}audio=f;msg("Áudio importado");}if(r==4){Uri tree=d.getData();Uri parent=android.provider.DocumentsContract.buildDocumentUriUsingTree(tree,android.provider.DocumentsContract.getTreeDocumentId(tree));File[] items=dir.listFiles((x,n)->n.startsWith(id));if(items!=null)for(File item:items){if(!item.isFile())continue;String mime=item.getName().endsWith(".pdf")?"application/pdf":item.getName().endsWith(".json")?"application/json":"audio/*";Uri out=android.provider.DocumentsContract.createDocument(getContentResolver(),parent,mime,item.getName());if(out==null)throw new IOException("Não foi possível criar arquivo");try(InputStream i=new FileInputStream(item);OutputStream o=getContentResolver().openOutputStream(out)){copy(i,o);}}msg("Arquivos copiados para a pasta escolhida");}if(r==3){try(ZipOutputStream z=new ZipOutputStream(getContentResolver().openOutputStream(d.getData()))){File[] fs=dir.listFiles((x,n)->n.endsWith(".json"));if(fs!=null)for(File f:fs){JSONObject j=new JSONObject(read(f));for(File item:new File[]{f,new File(dir,j.optString("audio")),new File(dir,f.getName().replace(".json","-ata.pdf")),new File(dir,f.getName().replace(".json","-avaliacao.pdf"))}){if(!item.isFile())continue;z.putNextEntry(new ZipEntry(item.getName()));try(InputStream i=new FileInputStream(item)){copy(i,z);}z.closeEntry();}}}msg("ZIP exportado");}}catch(Exception e){msg("Falha: "+e.getMessage());}}
 String stamp(){return new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm:ss",new Locale("pt","BR")).format(new Date());}
 void refreshTotal(){if(totalView==null)return;if(ausente.isChecked()){totalView.setText("Nota: não se aplica");return;}double t=0;for(int k=0;k<3;k++){try{double n=Double.parseDouble(val(notas[k]).replace(',','.'));if(!Double.isFinite(n)||n<0||n>max[k])throw new Exception();t+=n;notas[k].setError(null);}catch(Exception e){totalView.setText("Nota: avaliação incompleta ou inválida");if(!val(notas[k]).isEmpty())notas[k].setError("Informe nota de 0 a "+max[k]);return;}}totalView.setText(String.format(new Locale("pt","BR"),"Nota final: %.2f / 10",t));}
 void editDocument(boolean ficha){if(rec!=null){msg("Encerre a gravação");return;}LinearLayout l=new LinearLayout(this);l.setOrientation(1);ScrollView scroll=new ScrollView(this);scroll.addView(l);EditText[] originals={ins,nome,etnia,povo,territorio,banca,banca2,local,notas[0],notas[1],notas[2],obs};String[] labels={"Inscrição","Nome","Etnia","Povo","Território","Avaliador 1","Avaliador 2","Local",criterios[0],criterios[1],criterios[2],"Observações"};EditText[] edits=new EditText[originals.length];for(int k=0;k<edits.length;k++){edits[k]=field(l,labels[k]);edits[k].setText(val(originals[k]));edits[k].setInputType(originals[k].getInputType());}new AlertDialog.Builder(this).setTitle("Editar "+(ficha?"ficha":"ata")).setView(scroll).setPositiveButton("Aplicar",(a,b)->{for(int k=0;k<edits.length;k++)originals[k].setText(val(edits[k]));refreshTotal();msg("Alterações aplicadas. Salve o documento.");}).setNegativeButton("Cancelar",null).show();}
 void document(boolean ficha,int action){try{JSONObject j=snapshot(false);if(ficha&&ausente.isChecked())throw new Exception("Ficha de avaliação não se aplica a ausentes");pdf(j,ficha);File f=new File(dir,id+(ficha?"-avaliacao.pdf":"-ata.pdf"));if(action==1){msg("PDF salvo no dispositivo");return;}if(action==2){pendingPdf=f;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,val(ins).replaceAll("[^a-zA-Z0-9_-]","_")+(ficha?"-ficha.pdf":"-ata.pdf"));startActivityForResult(i,5);return;}ScrollView scroll=new ScrollView(this);LinearLayout pages=new LinearLayout(this);pages.setOrientation(1);scroll.addView(pages);try(android.os.ParcelFileDescriptor fd=android.os.ParcelFileDescriptor.open(f,android.os.ParcelFileDescriptor.MODE_READ_ONLY);android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(fd)){for(int k=0;k<renderer.getPageCount();k++){try(android.graphics.pdf.PdfRenderer.Page page=renderer.openPage(k)){android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(page.getWidth()*2,page.getHeight()*2,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xffffffff);page.render(bitmap,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);ImageView view=new ImageView(this);view.setAdjustViewBounds(true);view.setImageBitmap(bitmap);pages.addView(view,new LinearLayout.LayoutParams(-1,-2));}}}new AlertDialog.Builder(this).setTitle(ficha?"Ficha de avaliação":"Ata da entrevista").setView(scroll).setPositiveButton("Fechar",null).show();}catch(Exception e){msg("Documento: "+e.getMessage());}}
 void pdf(JSONObject j,boolean ficha)throws Exception{
 android.graphics.pdf.PdfDocument doc=new android.graphics.pdf.PdfDocument();
 android.graphics.Paint p=new android.graphics.Paint(3);p.setTextSize(12);
 ArrayList<String> lines=new ArrayList<>();Collections.addAll(lines,"UNIVERSIDADE FEDERAL DO OESTE DO PARÁ — UFOPA","PROCESSO SELETIVO ESPECIAL INDÍGENA — PSEI 2027",ficha?"FICHA DE AVALIAÇÃO DA BANCA":"ATA DE ENTREVISTA","","Nome: "+j.optString("nome"),"Inscrição: "+j.optString("inscricao"),"Etnia: "+j.optString("etnia"),"Povo: "+j.optString("povo"),"Território: "+j.optString("territorio"),"Avaliador 1: "+j.optString("banca"),"Avaliador 2: "+j.optString("banca2"),"Local: "+j.optString("local"),"Data do registro: "+j.optString("data"),"Início: "+j.optString("inicio")+"   Término: "+j.optString("fim"),"Presença: "+j.optString("presenca"),"Áudio: "+j.optString("audio"),"");
 if(ficha){JSONArray a=j.getJSONArray("notas");for(int k=0;k<a.length();k++)lines.add(criterios[k]+": "+a.getString(k)+" / "+max[k]);}
 if(!ficha){lines.add("REGISTRO CIRCUNSTANCIADO");lines.add("Na data e local acima identificados, reuniu-se a banca avaliadora, composta por "+j.optString("banca")+" e "+j.optString("banca2")+", para a entrevista individual do(a) candidato(a) "+j.optString("nome")+", no âmbito do Processo Seletivo Especial Indígena da UFOPA.");lines.add("Ausente".equals(j.optString("presenca"))?"Registrou-se a ausência do(a) candidato(a), não sendo realizada a entrevista nem atribuída nota.":"A banca registrou a realização da entrevista e a avaliação segundo os critérios do instrumento de avaliação do certame, com o resultado abaixo.");}
 lines.add("Nota final: "+(j.isNull("total")?"Não se aplica":j.optString("total")));lines.add("Observações / fundamentação: "+j.optString("observacoes"));
 if(!ficha)lines.add("Nada mais havendo a registrar, lavrou-se a presente ata para conferência e assinatura dos dois avaliadores.");
 int pageNo=1,y=95;android.graphics.pdf.PdfDocument.Page page=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,pageNo).create());
 decorate(page.getCanvas(),pageNo);for(String line:lines){for(String part:line.split("\\n",-1)){String rest=part;do{int n=p.breakText(rest,true,505,null);if(n==0&&rest.length()>0)n=1;if(y>770){doc.finishPage(page);page=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,++pageNo).create());y=95;decorate(page.getCanvas(),pageNo);}page.getCanvas().drawText(rest.substring(0,n),45,y,p);y+=19;rest=rest.substring(n);}while(!rest.isEmpty());}}
 if(y>650){doc.finishPage(page);page=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,++pageNo).create());y=95;decorate(page.getCanvas(),pageNo);}for(String key:new String[]{"banca","banca2"}){y+=45;page.getCanvas().drawLine(45,y,550,y,p);y+=18;page.getCanvas().drawText(j.optString(key),45,y,p);}
 doc.finishPage(page);try(FileOutputStream o=new FileOutputStream(new File(dir,id+(ficha?"-avaliacao.pdf":"-ata.pdf")))){doc.writeTo(o);}finally{doc.close();}
 }
 void decorate(android.graphics.Canvas c,int page){android.graphics.Paint p=new android.graphics.Paint(3);p.setColor(0xff174a78);c.drawRect(0,0,595,65,p);p.setColor(0xffffffff);p.setTextSize(19);p.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);c.drawText("BANZEIRO PSEI  |  UFOPA",45,38,p);p.setColor(0xff168577);c.drawRect(0,65,595,69,p);p.setColor(0xffe8a052);c.drawRect(0,69,595,71,p);p.setColor(0xff174a78);c.drawRect(45,798,550,800,p);p.setTextSize(9);c.drawText("Registro e avaliação de entrevistas • Página "+page,45,815,p);}
